{"content": "import flask
from flask.sessions import SessionInterface, SessionMixin


def test_custom_session_interface():
    """A custom SessionInterface implementation can be assigned to
    app.session_interface and used to handle sessions.
    """

    class CustomSession(dict, SessionMixin):
        pass

    class CustomSessionInterface(SessionInterface):
        def open_session(self, app, request):
            return CustomSession()

        def save_session(self, app, session, response):
            pass

    app = flask.Flask(__name__)
    app.session_interface = CustomSessionInterface()

    @app.route("/")
    def index():
        flask.session["key"] = "value"
        return flask.session["key"]

    with app.test_client() as client:
        resp = client.get("/")
        assert resp.data == b"value"", "path": "tests/test_custom_session_interface.py"}
